from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    separate_groups = []  # Step 2: Initialize an empty list to store separate groups
    stack = []
    start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                group = paren_string[start:i+1]
                if group.count('(') == group.count(')'):
                    separate_groups.append(group)  # Step 6: Add the balanced group to the list

    return separate_groups  # Step 7: Return the list of separate groups

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']
